  1716          switch (m->type) {
  1717          case FILE_BYTE:
  1718                  v = p->b;
  1719                  break;
  1720
  1721          case FILE_SHORT:
  1722          case FILE_BESHORT:
  1723          case FILE_LESHORT:
  1724                  v = p->h;
  1725                  break;
  1726
  1727          case FILE_LONG:
