  1745          case FILE_QDATE:
  1746          case FILE_BEQDATE:
  1747          case FILE_LEQDATE:
  1748          case FILE_QLDATE:
  1749          case FILE_BEQLDATE:
  1750          case FILE_LEQLDATE:
